/**
 * ZyniVerse config plugin — WDAC-safe Hermes compiler path.
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so editing
 * `android/app/build.gradle` by hand is lost on the next prebuild. This plugin
 * re-applies an opt-in override on the generated `hermesCommand` line:
 *
 *   -PzyniHermescPath=<path to hermesc.exe>
 *
 * On Windows, Application Control (Device Guard) blocks executables inside
 * `node_modules`, including Hermes' compiler. `scripts/copy-hermesc.ps1` copies
 * it (plus its DLLs) to an allow-listed location and prints the path to pass.
 * With no override, the default React Native path is untouched, so this plugin
 * is harmless on machines without the policy.
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const MARKER = 'zyniHermescPath';
const COMMENT =
  '// ZyniVerse: opt-in Hermes compiler override (see scripts/copy-hermesc.ps1)';

/** Pure transform, exported for a quick node-level sanity check. */
function applyHermesOverride(contents) {
  if (typeof contents !== 'string' || contents.includes(MARKER)) return contents;

  const newline = contents.includes('\r\n') ? '\r\n' : '\n';
  return contents.replace(/^([ \t]*)hermesCommand = (.*)$/m, (match, indent, rhs) => {
    const expression = rhs.trim();
    if (!expression) return match;
    return [
      `${indent}${COMMENT}`,
      `${indent}def localHermesc = project.findProperty("${MARKER}")`,
      `${indent}hermesCommand = localHermesc ? localHermesc.toString() : (${expression})`,
    ].join(newline);
  });
}

module.exports = function withZyniHermes(config) {
  return withAppBuildGradle(config, (configProps) => {
    if (configProps.modResults.language !== 'groovy') return configProps;
    configProps.modResults.contents = applyHermesOverride(
      configProps.modResults.contents
    );
    return configProps;
  });
};

module.exports.applyHermesOverride = applyHermesOverride;
